    for (word, want) in rows {
        let insn = decode(0, *word)
            .unwrap_or_else(|| panic!("word {word:#010x} ({want}) not decoded"));
        let got = mnemonic_of(&insn);
        assert_eq!(
            &got,
            want,
            "word {word:#010x}: decoder says {got:?}, capstone says {want:?}"
        );
        checked += 1;
    }
    assert!(checked >= 100, "golden table shrunk: {checked}");
